import java.io.*;
import java.nio.file.*;
import java.util.*;
import javax.xml.stream.*;
import org.junit.platform.engine.TestExecutionResult;
import org.junit.platform.engine.discovery.DiscoverySelectors;
import org.junit.platform.launcher.*;
import org.junit.platform.launcher.core.*;
import org.junit.platform.launcher.listeners.*;

/** Uses the unchanged JUnit 5 engines and compiled Gradle runtime classpath. */
public final class VanQualifiedTestLauncher {
  record Case(String id, String name, String state, String message, double seconds) {}
  public static void main(String[] args) throws Exception {
    var records = new ArrayList<Case>();
    var starts = new HashMap<String,Long>();
    var summary = new SummaryGeneratingListener();
    var recorder = new TestExecutionListener() {
      public void executionStarted(TestIdentifier t) { if(t.isTest()) starts.put(t.getUniqueId(),System.nanoTime()); }
      public void executionSkipped(TestIdentifier t, String why) { if(t.isTest()) records.add(new Case(t.getUniqueId(),t.getDisplayName(),"SKIPPED",why,0)); }
      public void executionFinished(TestIdentifier t, TestExecutionResult r) {
        if(t.isTest()) records.add(new Case(t.getUniqueId(),t.getDisplayName(),r.getStatus().name(),r.getThrowable().map(Throwable::toString).orElse(""),(System.nanoTime()-starts.getOrDefault(t.getUniqueId(),System.nanoTime()))/1e9));
      }
    };
    var request = LauncherDiscoveryRequestBuilder.request().selectors(DiscoverySelectors.selectClasspathRoots(Set.of(Path.of(args[0]).toAbsolutePath()))).build();
    var launcher=LauncherFactory.create();
    launcher.registerTestExecutionListeners(summary,recorder);
    launcher.execute(request);
    var s=summary.getSummary();
    s.printTo(new PrintWriter(System.out,true)); s.printFailuresTo(new PrintWriter(System.out,true));
    try(var out=Files.newOutputStream(Path.of(args[1]))) {
      var x=XMLOutputFactory.newFactory().createXMLStreamWriter(out,"UTF-8");
      x.writeStartDocument("UTF-8","1.0");x.writeStartElement("testsuites");x.writeStartElement("testsuite");
      x.writeAttribute("name","unchanged-full-Kotlin-JUnit5-harness");x.writeAttribute("tests",Long.toString(s.getTestsFoundCount()));
      x.writeAttribute("failures",Long.toString(s.getTestsFailedCount()));x.writeAttribute("errors",Long.toString(s.getContainersFailedCount()));
      x.writeAttribute("skipped",Long.toString(s.getTestsSkippedCount()+s.getTestsAbortedCount()));
      x.writeAttribute("time",Double.toString((s.getTimeFinished()-s.getTimeStarted())/1000.0));
      for(var c:records) {
        x.writeStartElement("testcase");x.writeAttribute("name",c.name);x.writeAttribute("classname",c.id);x.writeAttribute("time",Double.toString(c.seconds));
        if(!c.state.equals("SUCCESSFUL")) {x.writeStartElement(c.state.equals("SKIPPED")||c.state.equals("ABORTED")?"skipped":"failure");x.writeAttribute("message",c.message);x.writeEndElement();}
        x.writeEndElement();
      }
      x.writeEndElement();x.writeEndElement();x.writeEndDocument();x.close();
    }
    if(records.size()!=s.getTestsFoundCount() || s.getTestsFoundCount()!=1330 || s.getTestsSucceededCount()!=1330 || s.getContainersFailedCount()!=0 || s.getTestsAbortedCount()!=0 || s.getTestsSkippedCount()!=0) System.exit(1);
  }
}
